108	function parseLegacyFactualityResponse(responseText: string): { option: string; reason: string } {
109	  const answerMatch = responseText.match(/\s*\(?([a-eA-E])\)/);
110	  if (!answerMatch) {
111	    throw new Error(`Factuality checker output did not match expected format: ${responseText}`);
112	  }
113	
114	  const option = answerMatch[1].toUpperCase();
115	  const reasonMatch = responseText.match(/\)\s*(.*)/s);
116	
117	  return {
118	    option,
119	    reason: reasonMatch?.[1] ? reasonMatch[1].trim() : responseText,
120	  };
121	}
