40	  if (!rubricPrompt) {
41	    return defaultPrompt;
42	  }
43	
44	  if (typeof rubricPrompt === 'object' && Object.keys(rubricPrompt).length === 0) {
45	    return defaultPrompt;
46	  }
47	
48	  if (typeof rubricPrompt === 'string' && rubricPrompt.startsWith('file://')) {
49	    const basePath = cliState.basePath || '';
50	
51	    // Render Nunjucks templates in the file path (e.g., file://{{ env.RUBRIC_PATH }}/rubric.json)
52	    const renderedFilePath = getNunjucksEngineForFilePath().renderString(rubricPrompt, {});
